// Verify AssetNest HMAC-SHA256 signature BEFORE any business logic.
// Secret: set WEBHOOK_SECRET in your n8n environment (Project Settings → Variables),
// or hard-code here only for testing (never commit real secrets).
// If your n8n restricts require(), allow the built-in: NODE_FUNCTION_ALLOW_BUILTIN=crypto
const { createHmac, timingSafeEqual } = require('crypto');
const SECRET = $env.WEBHOOK_SECRET;
if (!SECRET) { throw new Error('WEBHOOK_SECRET is not set'); }

const item = $input.first();
const raw = item.binary?.data ? item.binary.data.toString('utf8') : JSON.stringify(item.json.body ?? item.json);
const header = item.json.headers['x-assetnest-signature'];
const deliveryId = item.json.headers['x-assetnest-delivery'];

const match = /^t=(\d+),v1=([0-9a-f]{64})$/.exec(header ?? '');
if (!match) { throw new Error('malformed signature header'); }
const [, t, digest] = match;
if (Math.abs(Date.now() / 1000 - Number(t)) > 300) { throw new Error('timestamp skew too large (possible replay)'); }
const expected = createHmac('sha256', SECRET).update(`${t}.${raw}`).digest('hex');
if (!timingSafeEqual(Buffer.from(digest, 'hex'), Buffer.from(expected, 'hex'))) {
  throw new Error('signature mismatch');
}

const body = JSON.parse(raw);
return [{ json: {
  verified: true,
  deliveryId,
  event: body.kind,
  eventId: body.id,
  occurredAt: body.occurredAt,
  workspaceId: body.workspaceId,
  resourceId: body.resourceId,
  payload: body.payload,
} }];
